@lru_cache(maxsize=1)
def _get_t2s_trans_table() -> dict[int, int]:
    raw = zlib.decompress(base64.b85decode(_DATA_B85)).decode("utf-8")
    src, dst = raw.split("	")
    return str.maketrans(src, dst)


def fold_cjk_t2s(text: str) -> str:
    """Convert Traditional Chinese characters to Simplified Chinese without segmenting phrases."""
    return text.translate(_get_t2s_trans_table())
